  def pOr(cs: Iterable[CFormula])(implicit ta: TypeAnalyzer, negate: Boolean) = 
    if (negate) and(cs) else or(cs)
  def pUpperBound(i: _InferenceVarType, t: Type)(implicit negate: Boolean) = 
