  def pLowerBound(i: _InferenceVarType, t: Type)(implicit negate: Boolean) = 
    if (negate) notLowerBound(i, t) else lowerBound(i, t)
  def pExclusion(i: _InferenceVarType, t: Type)(implicit negate: Boolean) = 
